import {HELP_CONTENT as C} from './help-content.js';
export const HELP_SECTIONS=['play','updates','progress'];
export const normalizeHelpSection=s=>HELP_SECTIONS.includes(s)?s:'play';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paragraphs=s=>s.split('\n').map(x=>`<p>${escape(x)}</p>`).join('');
function play(){return `<section aria-labelledby="help-play"><h2 id="help-play">처음에는 다섯 가지만</h2><p class="help-lead">돈을 많이 버는 것만 목표로 삼지 않아도 괜찮아요. 같은 시대에 내가 어떤 생활을 고르고 무엇을 배웠는지 남기는 게임입니다.</p><ol class="help-steps">${C.steps.map(([title,body],i)=>`<li><span class="help-number">0${i+1}</span><div><h3>${escape(title)}</h3>${paragraphs(body)}</div></li>`).join('')}</ol><h2>네 메뉴만 기억하세요</h2><div class="help-menu-grid">${C.menus.map(([title,body])=>`<article><h3>${escape(title)}</h3><p>${escape(body)}</p></article>`).join('')}</div><h2>돈이 움직이는 기능</h2><p>필요한 항목만 펼쳐 읽으세요.</p>${C.finance.map(([t,b])=>`<details class="help-detail"><summary>${escape(t)}</summary>${paragraphs(b)}</details>`).join('')}<h2>막혔을 때 찾아보기</h2>${C.faq.map(([t,b])=>`<details class="help-detail"><summary>${escape(t)}</summary>${paragraphs(b)}</details>`).join('')}</section>`;}
function updates(){return `<section aria-labelledby="help-updates"><h2 id="help-updates">어떤 점이 바뀌었나요?</h2><p>최신 내용부터 보여드립니다. 이전 버전은 제목을 눌러 펼치세요. 공개 날짜는 확인된 기록이 없어 임의로 붙이지 않았습니다.</p><div class="help-releases">${C.releases.map(([v,t,items],i)=>`<details class="help-detail help-release" ${i===0?'open':''}><summary><span class="help-version">${escape(v)}</span><span>${escape(t)}</span></summary><ul>${items.map(x=>`<li>${escape(x)}</li>`).join('')}</ul></details>`).join('')}</div><p class="help-note">과거 패치 설명은 그 버전 기준입니다. 현재 기능과 한계는 ‘개발 현황’에서 확인하세요.</p></section>`;}
function progress(){const p=C.progress;return `<section aria-labelledby="help-progress"><h2 id="help-progress">현재는 플레이 가능한 학습용 베타</h2><p class="help-lead">시작부터 선택·가계 계산·생애 결산까지의 틀은 있습니다. 실제 한국 경제 전체를 재현한 완성작은 아닙니다.</p><div class="help-counts">${[[p.historyCards,'진행 역사 카드'],[p.backgroundCards,'시작 전 배경 카드'],[p.topics,'원본 요청 주제']].map(([n,t])=>`<article><b>${n}</b><span>${t}</span></article>`).join('')}</div><div class="help-note"><p>원본 ${p.topics}개 주제: 학습 연결 ${p.connected}개 · 부분 연결 ${p.partial}개 · 배경 연결 ${p.backgroundTopics}개.</p><p>카드 수에는 한 주제를 여러 시점으로 나눈 카드와 추가 지표가 포함됩니다. ${p.historyCards}개 카드가 ${p.historyCards}개 요청 주제의 완료를 뜻하지 않습니다. 학습 연결도 실제 손익 계산 완료를 뜻하지 않습니다.</p></div><div class="help-table-wrap"><table class="help-table"><caption>구현 범위와 남은 작업</caption><thead><tr><th scope="col">영역</th><th scope="col">상태</th><th scope="col">현재 범위</th></tr></thead><tbody>${C.features.map(([t,s,b])=>`<tr><th scope="row">${escape(t)}</th><td>${escape(s)}</td><td>${escape(b)}</td></tr>`).join('')}</tbody></table></div><details class="help-detail"><summary>자료 연결 범위를 자세히 보기</summary><p>지역 선택 ${p.regions}곳 · 로또 1~${p.lotteryRounds.toLocaleString('ko-KR')}회 내장.</p><p>공식 정책금리 참고 ${p.rateReferences}개 · 연간 CPI ${p.cpiYears}개 연도(2002~2024년). 공식 지표와 게임의 금융 가격은 구분합니다.</p><p>로또 초기 1,156회는 두 사본 대조, 최근 89회는 민간 API 자료입니다. 전 회차를 공식 원자료로 검증한 상태는 아닙니다. 회차 1,245는 이 파일의 자료 범위이며 ‘오늘의 최신 회차’라고 주장하지 않습니다.</p><p>지역의 집값과 임대료, 모든 연도의 소득·보험·사고 확률을 실제 통계로 채운 상태는 아닙니다.</p></details><h2>다음 작업의 우선순위</h2><ol class="help-next"><li>실제 브라우저·휴대폰에서 안내와 금융 기능을 검증하고 불편한 흐름을 고칩니다.</li><li>과거 금융상품·생활비·소득·집값 자료를 검증해 모형을 하나씩 교체합니다.</li><li>부분 연결된 주제의 정책 단계와 지역·직업·계약별 적용을 보완합니다.</li><li>계산과 밸런스가 안정된 뒤 다중 엔딩·승리 조건·온라인 랭킹을 붙입니다.</li></ol><p>작업량 기준을 정하지 않은 전체 완성률 %는 제시하지 않습니다. 아래 목표들은 계획이며 아직 구현된 기능이 아닙니다.</p></section>`;}
export function renderHelp(section='play',{standalone=false}={}){section=normalizeHelpSection(section);return `<main id="main" class="help-shell"><header class="help-heading"><span class="eyebrow">IF 세계 · v${C.version} / GUIDE &amp; UPDATES</span><h1>어렵지 않게,<br>나의 세계 시작하기.</h1><p>플레이 방법과 지금까지의 변화를 한곳에 모았습니다.</p>${standalone?'<a class="help-back" href="index.html">← 게임 시작 화면으로</a>':'<button class="help-back" data-ui="guide-back">← 원래 화면으로</button>'}</header><nav class="help-navigation" aria-label="플레이 안내 메뉴">${[['play','플레이 안내'],['updates','패치노트'],['progress','개발 현황']].map(([id,t])=>`<button data-help-section="${id}" aria-current="${section===id?'page':'false'}" class="${section===id?'active':''}">${t}</button>`).join('')}</nav>${section==='updates'?updates():section==='progress'?progress():play()}<footer class="help-foot">안내를 읽어도 게임 시간과 자산은 바뀌지 않습니다.<br>금융상품과 가격의 모형 범위를 확인하며 즐겨 주세요.</footer></main>`;}
